            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "There are many people in England, and perhaps elsewhere, who seem to be unable to contemplate military operations for clear political objects, unless they can cajole themselves into the belief that their enemy are utterly and hopelessly vile.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "This may be very comforting to philanthropic persons at home; but when an army in the field becomes imbued with the idea that the enemy are vermin who cumber the earth, instances of barbarity may easily be the outcome.", Author = "Winston Churchill" },
