            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "It is the abiding fear and hatred of the movement that seeks to place the native on a level with the white man.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "There must be room in our army system for nearly everyone who is not grossly idle or grossly stupid.", Author = "Winston Churchill" },
