            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "It is a case of finding suitable employment for officers not fit for higher command.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "It must be remembered that an army is not a field upon which persons with Utopian ideas may exercise their political theories, but a weapon for the defence of the State.", Author = "Winston Churchill" },
