            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The wars of peoples will be more terrible than those of kings.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The whole Bill looks like an attempt on the part of the Government to gratify a small but noisy section of their own supporters and to purchase a little popularity in the constituencies by dealing harshly with a number of unfortunate aliens who have no votes.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "It will commend itself to those who like patriotism at other people's expense and admire Imperialism on the Russian model.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "It is expected to appeal to insular prejudice against foreigners, to racial prejudice against Jews, and to labour prejudice against competition; and it will no doubt supply a variety of rhetorical phrases for the approaching election.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The same men who are obstinate opponents of trade unionism will declaim about 'the rights of British labour.'", Author = "Winston Churchill" },
