            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "Those who have been most forward in bringing Chinese into Africa will pose as the champions of racial purity at home.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "I take leave to doubt the wisdom of this Bill even as a political manoeuvre.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "In spite of militarism and false ideals about trade, there is a growing spirit of fraternity between democracies.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "English working men are not so selfish as to be unsympathetic towards the victims of circumstances or oppression.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "Every vote given for Protection is a vote to give Governments the right of robbing Peter to pay Paul and charging the public a handsome commission on the job.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The doctrines that by keeping out foreign goods more wealth, and consequently more employment, will be created at home, are either true or they are not true.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "We contend that for a nation to try to tax itself into prosperity is like a man standing in a bucket and trying to lift himself up by the handle.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "For my own part I have always felt that a politician is to be judged by the animosities which he excites among his opponents.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "I have always set myself not merely to relish but to deserve thoroughly their censure.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "Where there is great power there is great responsibility, where there is less power there is less responsibility, and where there is no power there can, I think, be no responsibility.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "Sentiment by the bucketful, patriotism and Imperialism by the Imperial pint, the open hand at the public Exchequer, the open door at the publichouse, dear food for the million, cheap labour for the millionaire.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "That was the policy which the Tory party offered them, and that was the policy which he asked them to strike at with the battle-axe of Scotland.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The Times is speechless, and takes three columns to express its speechlessness.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "Uncounted generations will trample heedlessly upon our tombs.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "What is the use of living, if it be not to strive for noble causes and to make this muddled world a better place for those who will live in it after we are gone?", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "How else can we put ourselves in harmonious relation with the great verities and consolations of the infinite and the eternal?", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "And I avow my faith that we are marching towards better days.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "Humanity will not be cast down.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "We are going on swinging bravely forward along the grand high road and already behind the distant mountains is the promise of the sun.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The quarrel between a tremendous democratic electorate and a one-sided hereditary chamber of wealthy men has often been threatened, has often been averted, has been long debated, has been long delayed, but it has always been inevitable, and it has come at last.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "It is now open, it is now flagrant, and it must now be carried to a conclusion.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "Why should five hundred or six hundred titled persons govern us, and why should their children govern our children for ever?", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "I invite a reply from the apologists and the admirers of the House of Lords.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "I invite them to show any ground of reason, or of logic, or of expediency or practical common sense in defence of the institution which has taken the predominant part during the last few days in the politics of our country.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "There is no defence, and there is no answer, except that the House of Lords...has survived out of the past.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "It is a lingering relic of a feudal order.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "It is the remains, the solitary reminder of a state of things and of a balance of forces which has wholly passed away.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "There is no difficulty in vindicating the principle of a hereditary monarchy.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "There is no precedent of any kind for the rejection of a Budget Bill by the House of Lords in all the long annals of the British Parliament, or, before that, in the still more venerable annals of the English Parliament.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The custom of centuries forbids their intrusion upon finance.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The House of Lords have only been tolerated all these years because they were thought to be in a comatose condition which preceded dissolution.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "They have got to dissolution now.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "All civilization, said Lord Curzon, quoting Renan, 'all civilization has been the work of aristocracies'. ... It would be much more true to say 'The upkeep of aristocracies has been the hard work of all civilizations'.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "I cannot believe that you by your votes are going to constitute them the main foundation on which the governing power in our land is reposed.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "I cannot believe that the middle classes and the working classes, who after all have only to use their voting strength to get their own way, are going to degrade and cast away their own voting powers which their fathers won for them in the past...", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "I cannot believe that the electors are going obsequiously to hand over their most vital constitutional right, namely, to choose the Chamber that governs the Government, to an antiquated body of titled persons utterly beyond their control.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "There is nothing economically unsound in increasing temporarily and artificially the demand for labour during a period of temporary and artificial contraction.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "There is a plain need of some averaging machinery to regulate and even-up the general course of the labour market.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "We have entered upon a period of crisis and conflict more grave and crucial than any living man has known, and it is a conflict which I think has been more deliberately undertaken and will be more resolutely fought through by both sides than any political conflict that we can recall.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "Terribly important as economic and constitutional questions may be, the fiscal system of a country and the system of Government which prevails in a country are only means to an end, and that end must be to create conditions favourable to the social and moral welfare of the masses of the citizens.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "We have left the wilderness of phrases and formulas, the cut and dried party issues, and we have broken violently into a world of constructive action.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "It would be an exaggeration to speak of these changes as though they were a revolution.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The social conditions of the British people in the early years of the twentieth century cannot be contemplated without deep anxiety...", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "We are at the cross-ways.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "No, it is here in our midst, close at home, close at hand in the vast growing cities of England and Scotland, and in the dwindling and cramped villages of our denuded countryside.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "Beware lest they shatter the foundations of her power.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The Budget, and the policy of the Budget, is the first conscious attempt on the part of the State to build up a better and a more scientific organization of society for the workers of this country.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "Liberalism supplies at once the higher impulse and the practicable path; it appeals to persons by sentiments of generosity and humanity; it proceeds by courses of moderation.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "By gradual steps, by steady effort from day to day, from year to year, Liberalism enlists hundreds of thousands upon the side of progress and popular democratic reform whom militant Socialism would drive into violent Tory reaction...", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The cause of the Liberal Party is the cause of the left-out millions.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The whole tendency of civilization is...towards the multiplication of the collective functions of society.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The ever growing complications of civilization create for us new services which have to be undertaken by the State, and create for us an expansion of the existing services.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "We may do something better with the canals, and we are all agreed that the State must increasingly and earnestly concern itself with the care of the sick and aged, and, above all, of the children.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "I look forward to the universal establishment of minimum standards of life and labour, and their progressive elevation as the increasing energies of production may permit.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "I do not think that Liberalism in any circumstances can cut itself off from this fertile field of social effort, and I would recommend you not to be scared in discussing any of these proposals, just because some old woman comes along and tells you they are Socialistic.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "Roads are made, streets are made, services are improved, electric light turns night into day, water is brought from reservoirs a hundred miles off in the mountains -- and all the while the landlord sits still.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "Every one of those improvements is effected by the labour and cost of other people and the taxpayers.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "To not one of those improvements does the land monopolist, as a land monopolist, contribute, and yet by every one of them the value of his land is enhanced.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "He renders no service to the community, he contributes nothing to the general welfare, he contributes nothing to the process from which his own enrichment is derived.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The mood and temper of the public in regard to the treatment of crime and criminals is one of the most unfailing tests of the civilisation of any country.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The unnatural and increasingly rapid growth of the feeble-minded and insane classes, coupled as it is with steady restriction among all the thrifty, energetic and superior stocks constitutes a national and race danger which is impossible to exaggerate.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "I feel that the source from which the stream of madness is fed should be cut off and sealed before another year has passed.", Author = "Winston Churchill" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "I consider that every workman is well advised to join a trade union.", Author = "Winston Churchill" },
