            new Quote { Id = "https://en.wikiquote.org/wiki/Winston_Churchill", Text = "The main argument which all these years has sustained the Home Rule cause has been the continuous and unalterable demand of the Irish people in an overwhelming majority, through every recognised channel of the national will, for the establishment of an Irish Legislature.", Author = "Winston Churchill" },
